use crate::layout::{AxisGroup, RegionGeometry, SpeakerLayout, SpeakerPoint};
use crate::speaker::SpeakerChannel;

const fn pt(x: u16, y: u16, z: u16, speaker_id: u8) -> SpeakerPoint {
    SpeakerPoint {
        coordinate_q15: [x, y, z],
        speaker_id,
    }
}

const fn grp(size: u8, indices: [u8; 3]) -> AxisGroup {
    AxisGroup { size, indices }
}

const fn region(
    point_count: u8,
    mode: u8,
    axis0_group_count: u8,
    axis1_group_count: u8,
    points: &[SpeakerPoint],
    axis0_groups: &[AxisGroup],
    axis1_groups: &[AxisGroup],
) -> RegionGeometry {
    let mut point_array = [SpeakerPoint {
        coordinate_q15: [0, 0, 0],
        speaker_id: 0,
    }; 15];
    let mut axis0_array = [AxisGroup {
        size: 0,
        indices: [0, 0, 0],
    }; 4];
    let mut axis1_array = [AxisGroup {
        size: 0,
        indices: [0, 0, 0],
    }; 4];
    let mut index = 0;
    while index < points.len() {
        point_array[index] = points[index];
        index += 1;
    }
    index = 0;
    while index < axis0_groups.len() {
        axis0_array[index] = axis0_groups[index];
        index += 1;
    }
    index = 0;
    while index < axis1_groups.len() {
        axis1_array[index] = axis1_groups[index];
        index += 1;
    }
    RegionGeometry {
        point_count,
        mode,
        axis0_group_count,
        axis1_group_count,
        points: point_array,
        axis0_groups: axis0_array,
        axis1_groups: axis1_array,
    }
}

